// The engine bundle of EA1 (engine-aware design §5.1): K, the capability index of the installed null-graph (every
// export of every subpath, with its declaration and documentation, and a hand-reviewed map of its families), and H,
// the support manifest (what Wexy can run today: nothing, until adapters exist). Generated by dev/engine-bundle.mjs
// from the package and null-graph's own documentation, never edited by hand except families.json, and checked
// against both by test/engine.test.mjs. D, the documents, is docs.ts, kept apart so a page that needs only K and H
// does not carry the documents' text. Everything is frozen at load.

import bundleText from './bundle.json?raw';
import capabilitiesText from './capabilities.json?raw';
import { deepFreeze, type DeepReadonly } from './frozen';
import supportText from './support.json?raw';

export type SymbolKind = 'class' | 'function' | 'interface' | 'type' | 'const' | 'enum' | 'other';

export interface EngineSymbol {
    /** `<family>:<name>`, unique: no name is exported by two subpaths. */
    id: string;
    family: string;
    name: string;
    kind: SymbolKind;
    /** A WGSL source string or a builder of one: material for shaders, not a runtime API. */
    wgsl: boolean;
    /** The first paragraph of its doc comment; empty when it has none. */
    summary: string;
    /** As declared, with its doc comment and without private members. */
    declaration: string;
    /** The declaration file, under the package. */
    file: string;
    /** The bundled documents that mention it by name. */
    docIds: string[];
}

/** How a world relates to a family: it may use it, the host owns it, or it needs what Wexy does not ship. */
export type FamilyUse = 'world' | 'host' | 'external';

export interface EngineFamily {
    id: string;
    subpath: string;
    title: string;
    use: FamilyUse;
    reason: string | null;
    summary: string;
    keySymbols: string[];
    notes: string[];
    docs: string[];
    examples: string[];
    symbolCount: number;
}

export type SupportStatus = 'supported' | 'unsupported' | 'device-blocked' | 'unverified';

export interface SupportEntry {
    family: string;
    status: SupportStatus;
    /** The Wexy adapter that runs it; null until one exists. */
    adapter: string | null;
    reason: string;
}

export interface EngineBundle {
    version: string;
    engine: { name: string; version: string; packageHash: string };
    docs: { source: string; count: number; hash: string };
    capabilities: { families: number; symbols: number; hash: string };
    support: { hash: string };
    bundleHash: string;
}

/** The bundle, frozen at load: what a tool hands out is what was hashed. */
export const ENGINE = deepFreeze({
    capabilities: JSON.parse(capabilitiesText) as { version: string; engine: string; families: EngineFamily[]; symbols: EngineSymbol[]; familyIndex: string },
    support: JSON.parse(supportText) as { version: string; engine: string; entries: SupportEntry[] },
    bundle: JSON.parse(bundleText) as EngineBundle,
});

const BY_ID = new Map(ENGINE.capabilities.symbols.map(s => [s.id, s]));

/** One symbol by its id, as an `inspect_api` tool would return it. */
export function inspectSymbol(id: string): DeepReadonly<EngineSymbol> {
    const s = BY_ID.get(id);
    if (!s) throw new Error(`no symbol ${id} in null-graph ${ENGINE.bundle.engine.version}`);
    return s;
}
